if __name__ == "__main__":
    revise_domain("460", "460_ai_careers", AI,
                  "AI careers through specific research, engineering, evaluation, domain, and governance tasks, with evidence of hiring and workplace responsibility.",
                  "dated job descriptions and hiring records, credited project artifacts, BLS occupational profiles, NIST AI role and risk documentation, worker accounts, and training outcomes",
                  "Name role, sector, country, and date. Distinguish a job title, job posting, actual task, and forecast; avoid promising employment from a single tool skill.")
